for(int n=0;n<=7;++n) for(int bits=0;bits<(1<<n);++bits) {
    string s;for(int i=0;i<n;++i) s+=bits&(1<<i)?'a':'b';
    for(string t:vector<string>{"a","b","ab","aa","aab","abb","aaa"}) {
        int needA=count(t.begin(),t.end(),'a'),needB=t.size()-needA,best=INT_MAX;
        for(int i=0;i<n;++i){int ca=0,cb=0;for(int j=i;j<n;++j){ca+=s[j]=='a';cb+=s[j]=='b';if(ca>=needA&&cb>=needB)best=min(best,j-i+1);}}
        auto r=Solution().minWindow(s,t);
        if(best==INT_MAX)assert(r.empty());else {assert((int)r.size()==best);assert(s.find(r)!=string::npos);assert(count(r.begin(),r.end(),'a')>=needA);assert(count(r.begin(),r.end(),'b')>=needB);}
    }
}
